type Json = null | boolean | number | string | Json[] | { [key: string]: Json };
export function solve(input: Json): Json {
  const d = input as any;
  const matches: number[][] = [];
  for (const term of d.terms)
    for (let i = 0; i + term.length <= d.text.length; i++)
      if (d.text.slice(i, i + term.length) === term) matches.push([i, i + term.length]);
  matches.sort((a: number[], b: number[]) => a[0] - b[0] || a[1] - b[1]);
  const out: number[][] = [];
  for (const r of matches) {
    const last = out.at(-1);
    if (last && r[0] <= last[1]) last[1] = Math.max(last[1], r[1]);
    else out.push(r);
  }
  return out;
}
